#!/usr/bin/env node
/**
 * Uploads the full Belarusian Bible (Пераклад Уладзіслава Чарняўскага 2017,
 * 73 books) to Firestore collection `bible_bel_charniauski`.
 *
 * Source: scripts/bible/bible_seed_bel_charniauski.json.gz
 *         (generated by scripts/bible/convert-bel-charniauski.py from bible.by)
 *
 * Data model: one document per book → bible_bel_charniauski/{bookId}
 *   { id, name, order, chapterCount, chapters: { "1": [verse, …], … } }
 *
 * Dry-run by default — prints what would be written.
 * Pass --apply to actually write to Firestore (idempotent: skips existing docs).
 * Pass --force to overwrite existing docs.
 *
 * Usage:
 *   node scripts/bible/upload-bible-bel-charniauski-firestore.mjs
 *   node scripts/bible/upload-bible-bel-charniauski-firestore.mjs --apply
 *   node scripts/bible/upload-bible-bel-charniauski-firestore.mjs --apply --force
 *   node scripts/bible/upload-bible-bel-charniauski-firestore.mjs --apply --service-account /path/to/key.json
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import zlib from 'node:zlib';
import { promisify } from 'node:util';

const gunzip = promisify(zlib.gunzip);

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const DEFAULT_SOURCE   = path.join(ROOT, 'scripts/bible/bible_seed_bel_charniauski.json.gz');
const DEFAULT_SA_KEY   = path.join(ROOT, 'patchs/serviceAccountKey.json');
const COLLECTION       = 'bible_bel_charniauski';

// ── CLI args ──────────────────────────────────────────────────────────────────
function parseArgs(argv) {
  const opts = { apply: false, force: false, source: DEFAULT_SOURCE, serviceAccount: DEFAULT_SA_KEY };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--apply')            opts.apply = true;
    else if (arg === '--force')       opts.force = true;
    else if (arg === '--source')      opts.source = path.resolve(argv[++i]);
    else if (arg === '--service-account') opts.serviceAccount = path.resolve(argv[++i]);
    else if (arg === '--help' || arg === '-h') { printHelp(); process.exit(0); }
    else { console.error(`Unknown argument: ${arg}`); process.exit(1); }
  }
  return opts;
}

function printHelp() {
  console.log(`
Upload the Belarusian Chernyavski 2017 Bible (73 books) to Firestore collection '${COLLECTION}'.

Usage: node scripts/bible/upload-bible-bel-charniauski-firestore.mjs [options]

Options:
  --apply                  Write to Firestore (dry-run without this flag)
  --force                  Overwrite existing documents (default: skip)
  --source <file>          JSON.gz source file  (default: scripts/bible/bible_seed_bel_charniauski.json.gz)
  --service-account <file> Firebase service account key  (default: patchs/serviceAccountKey.json)
`.trim());
}

// ── Load source data ──────────────────────────────────────────────────────────
async function loadBooks(sourcePath) {
  const raw = await fs.readFile(sourcePath);
  let jsonBuf;
  if (sourcePath.endsWith('.gz')) {
    jsonBuf = await gunzip(raw);
  } else {
    jsonBuf = raw;
  }
  const data = JSON.parse(jsonBuf.toString('utf8'));
  return data.books;
}

// ── Dry run ───────────────────────────────────────────────────────────────────
function dryRun(books) {
  console.log(`\n[DRY RUN] Would write ${books.length} documents to Firestore collection '${COLLECTION}':\n`);
  for (const book of books) {
    const verseCount = book.chapters.reduce((s, ch) => s + ch.length, 0);
    console.log(`  ${COLLECTION}/${book.id.padEnd(6)}  "${book.name}"  →  ${book.chapters.length} chapters, ${verseCount} verses`);
  }
  console.log(`\nRun with --apply to write to Firestore.`);
}

// ── Firestore doesn't allow nested arrays → convert chapters array-of-arrays
// to a map: { "1": [verse, ...], "2": [...], ... }
function chaptersToMap(chapters) {
  const map = {};
  chapters.forEach((verses, i) => { map[String(i + 1)] = verses; });
  return map;
}

// ── Apply ─────────────────────────────────────────────────────────────────────
async function apply(books, opts) {
  const [{ default: admin }] = await Promise.all([import('firebase-admin')]);
  const saKey = JSON.parse(await fs.readFile(opts.serviceAccount, 'utf8'));
  admin.initializeApp({ credential: admin.credential.cert(saKey) });
  const db = admin.firestore();

  let created = 0;
  let skipped = 0;
  let updated  = 0;
  const errors = [];

  for (const book of books) {
    const ref = db.collection(COLLECTION).doc(book.id);
    try {
      if (opts.force) {
        await ref.set({
          id: book.id,
          name: book.name,
          order: book.order,
          chapterCount: book.chapters.length,
          chapters: chaptersToMap(book.chapters),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
        updated++;
        console.log(`  ✓ updated  ${book.id}  (${book.chapters.length} ch)`);
      } else {
        await ref.create({
          id: book.id,
          name: book.name,
          order: book.order,
          chapterCount: book.chapters.length,
          chapters: chaptersToMap(book.chapters),
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
        created++;
        console.log(`  ✓ created  ${book.id}  (${book.chapters.length} ch)`);
      }
    } catch (err) {
      if (!opts.force && err.code === 6) {
        // ALREADY_EXISTS — skip
        skipped++;
        console.log(`  – skipped  ${book.id}  (already exists)`);
      } else {
        errors.push({ id: book.id, err: err.message });
        console.error(`  ✗ error    ${book.id}  ${err.message}`);
      }
    }
  }

  console.log(`\nDone: ${created} created, ${updated} updated, ${skipped} skipped, ${errors.length} errors`);
  if (errors.length > 0) process.exit(1);
}

// ── Main ──────────────────────────────────────────────────────────────────────
async function main() {
  const opts = parseArgs(process.argv.slice(2));

  console.log(`Source: ${opts.source}`);
  const books = await loadBooks(opts.source);
  console.log(`Loaded: ${books.length} books, ${books.reduce((s, b) => s + b.chapters.reduce((ss, ch) => ss + ch.length, 0), 0)} verses total`);

  if (!opts.apply) {
    dryRun(books);
    return;
  }

  try {
    await fs.access(opts.serviceAccount);
  } catch {
    console.error(`\nService account key not found: ${opts.serviceAccount}`);
    console.error('Pass --service-account <path> or place the key at patchs/serviceAccountKey.json');
    process.exit(1);
  }

  console.log(`\n[APPLY] Writing to Firestore collection '${COLLECTION}'...\n`);
  await apply(books, opts);
}

main().catch(err => { console.error(err); process.exit(1); });
